changeSet.sql:
DO $$
DECLARE
    t text;
    flags boolean;
BEGIN
    FOREACH t IN ARRAY ARRAY['siamois_document', 'siamois_document_aud']
    LOOP
        IF to_regclass('public.' || t) IS NOT NULL
           AND EXISTS (SELECT 1 FROM information_schema.columns
                       WHERE table_schema = 'public' AND table_name = t AND column_name = 'fk_document_type') THEN
            EXECUTE format('ALTER TABLE %I ADD COLUMN IF NOT EXISTS fk_category bigint', t);
            flags := EXISTS (SELECT 1 FROM information_schema.columns
                             WHERE table_schema = 'public' AND table_name = t AND column_name = 'fk_document_type_mod');
            IF flags THEN
                EXECUTE format('ALTER TABLE %I ADD COLUMN IF NOT EXISTS fk_category_mod boolean', t);
                EXECUTE format('UPDATE %I SET fk_category = fk_type, fk_type = fk_document_type, '
                               || 'fk_category_mod = fk_type_mod, fk_type_mod = fk_document_type_mod', t);
                EXECUTE format('ALTER TABLE %I DROP COLUMN fk_document_type_mod', t);
            ELSE
                EXECUTE format('UPDATE %I SET fk_category = fk_type, fk_type = fk_document_type', t);
            END IF;
            EXECUTE format('ALTER TABLE %I DROP COLUMN fk_document_type', t);
        END IF;
    END LOOP;
END $$;

-- -704: the type (was the category), -705: the category (was the type)
DO $$
BEGIN
    IF to_regclass('public.custom_field') IS NOT NULL THEN
        UPDATE custom_field SET label = 'document.field.type', value_binding = 'type', field_code = 'SIAD.TYPE'
        WHERE custom_field_id = -704 AND is_system_field;
        UPDATE custom_field SET label = 'document.field.category', value_binding = 'category', field_code = 'SIAD.CATEGORY'
        WHERE custom_field_id = -705 AND is_system_field;
    END IF;
END $$;
